package com.coffeeshop.service;
import com.coffeeshop.dto.TableManagementCommands;import com.coffeeshop.model.TableManagementModels;import com.coffeeshop.repository.TableManagementRepository;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class TableManagementServiceTest{private final Stub repository=new Stub();private final TableManagementService service=new TableManagementService(repository);@Test void normalizesAndSavesTable(){long id=service.saveTable(new TableManagementCommands.SaveTable(null," T01 "," Table 1 ",4,"AVAILABLE",1,true,null));assertEquals(42,id);assertEquals("T01",repository.saved.code());assertEquals("Table 1",repository.saved.name());}@Test void rejectsInvalidCodeNameCapacityStatusAndOrder(){assertThrows(IllegalArgumentException.class,()->service.saveTable(command(" ","Table",2,"AVAILABLE",0)));assertThrows(IllegalArgumentException.class,()->service.saveTable(command("T"," ",2,"AVAILABLE",0)));assertThrows(IllegalArgumentException.class,()->service.saveTable(command("T","Table",0,"AVAILABLE",0)));assertThrows(IllegalArgumentException.class,()->service.saveTable(command("T","Table",2,"UNKNOWN",0)));assertThrows(IllegalArgumentException.class,()->service.saveTable(command("T","Table",2,"AVAILABLE",-1)));}@Test void requiresVersionForUpdate(){assertThrows(IllegalArgumentException.class,()->service.saveTable(new TableManagementCommands.SaveTable(1L,"T","Table",2,"AVAILABLE",0,true,null)));}@Test void activatesAndDeactivatesAvailableTable(){TableManagementModels.CafeTable table=table("AVAILABLE");service.setActive(table,false);assertEquals(1,repository.activeId);assertFalse(repository.active);}@Test void refusesToDeactivateBusyTable(){assertThrows(IllegalStateException.class,()->service.setActive(table("OCCUPIED"),false));assertThrows(IllegalStateException.class,()->service.setActive(table("RESERVED"),false));}@Test void exposesRepositoryRows(){repository.rows=List.of(table("AVAILABLE"));assertEquals(1,service.tables().size());}private static TableManagementCommands.SaveTable command(String c,String n,int cap,String s,int order){return new TableManagementCommands.SaveTable(null,c,n,cap,s,order,true,null);}private static TableManagementModels.CafeTable table(String status){return new TableManagementModels.CafeTable(1,"T01","Table 1",4,status,1,true,new byte[]{1});}private static final class Stub implements TableManagementRepository{TableManagementCommands.SaveTable saved;List<TableManagementModels.CafeTable>rows=List.of();long activeId;boolean active;public List<TableManagementModels.CafeTable>tables(){return rows;}public List<TableManagementModels.Reservation>reservations(){return List.of();}public long saveTable(TableManagementCommands.SaveTable q){saved=q;return 42;}public void setTableActive(long id,boolean value,byte[]version){activeId=id;active=value;}public long saveReservation(TableManagementCommands.SaveReservation q){return 1;}}
}
